62		reader := bufio.NewReader(in)
63		debugLog := os.Getenv("ENTIRE_BRAIN_MCP_DEBUG_LOG")
64		mcpDebugLog(debugLog, "start")
65		for {
66			msg, frameMode, err := readMCPMessage(reader)
67			if errors.Is(err, io.EOF) {
68				mcpDebugLog(debugLog, "eof")
69				return nil
70			}
71			if errors.Is(err, errMCPRecoverable) {
72				// Reply with a JSON-RPC parse error and keep serving; one bad frame
73				// must not kill the whole MCP session.
74				mcpDebugLog(debugLog, "parse_error: "+err.Error())
75				resp := mcpMessage{JSONRPC: "2.0", Error: &mcpError{Code: -32700, Message: "parse error"}}
76				if werr := writeMCPMessage(out, resp, frameMode); werr != nil {
77					mcpDebugLog(debugLog, "write_error: "+werr.Error())
78					return werr
79				}
80				continue
81			}
82			if err != nil {
83				mcpDebugLog(debugLog, "read_error: "+err.Error())
84				return err
85			}
86			mcpDebugLog(debugLog, "message: "+msg.Method)
87			if msg.ID == nil {
88				continue
89			}
90			response := handleMCPMessage(ctx, opts, msg)
91			if err := writeMCPMessage(out, response, frameMode); err != nil {
92				mcpDebugLog(debugLog, "write_error: "+err.Error())
93				return err
94			}
95			mcpDebugLog(debugLog, "response: "+msg.Method)
96			mcpDebugLogToolResult(debugLog, msg, response)
97		}
98	}
